input.sparql:
SELECT ?point_uri ?timeseries_id WHERE {
  ?zone a brick:Zone ;
         rdfs:label "Basement" ;
         brick:hasPoint ?point .
  ?point brick:measures (brick:Electric_Power) ;
         ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?timeseries_id .
  VALUES ?occupancy_state { brick:Occupied }  # Unnecessary, but to clarify.
  ?point_occ brick:measures (brick:Occupancy) ;
         ref:hasExternalReference/ref:hasTimeseriesId ?timeseries_id_occ .
}
